-- including the EMOM / interval / max-reps / cumulative-ladder types added
-- to @rallypoint/fitness-shared's wodBodySchema in the same change.
-- INSERT OR IGNORE + wt_seed_<slug> ids match the 0006 convention; benchmark
-- rows carry description=NULL (per 0009 — the UI renders the movement rows).
-- Additive and backward-compatible: inserts only, no DDL.

-- Catalog top-up: Squat Clean (Badger, Linda) — the only movement these
-- benchmarks reference that 0002/0006 didn't already seed.
